export function balancearPedidos(quantidadeDeAtendentes, pedidos) {
  if (!Number.isInteger(quantidadeDeAtendentes) || quantidadeDeAtendentes <= 0) {
    throw new Error('quantidadeDeAtendentes precisa ser um inteiro positivo');
  }
  if (!Array.isArray(pedidos)) {
    throw new Error('pedidos precisa ser uma lista');
  }

  const grupos = Array.from({ length: quantidadeDeAtendentes }, () => []);

  // Rodízio: cada pedido vai para o atendente da sua posição % quantidade.
  for (let i = 0; i < pedidos.length; i++) {
    grupos[i % quantidadeDeAtendentes].push(pedidos[i]);
  }

  return grupos;
}
